import { Select } from '@absoluteui/components/select';

const host = document.createElement('div');
document.body.append(host);
const country = Select.create(host, {
  label: 'Country',
  name: 'country',
  required: true,
  options: [
    { value: 'in', label: 'India' },
    { value: 'gb', label: 'United Kingdom' },
    { value: 'us', label: 'United States' },
  ],
});
host.addEventListener('aui-change', () => {
  host.dataset.valid = String(country.validity.valid);
});

import { Select, type SelectChangeDetail } from '@absoluteui/components/select';

const host = document.createElement('div');
document.body.append(host);
Select.create(host, {
  label: 'Plan',
  value: 'team',
  options: [
    { value: 'free', label: 'Free', description: 'Up to 3 projects' },
    { value: 'team', label: 'Team', description: 'Unlimited projects' },
    { value: 'enterprise', label: 'Enterprise', description: 'Contact sales', disabled: true },
  ],
  validate: (value) => (value === 'free' ? 'The free plan does not include SSO.' : null),
});
host.addEventListener('aui-change', (event) => {
  const detail = (event as CustomEvent<SelectChangeDetail>).detail;
  host.dataset.plan = detail.value ?? '';
});
